"""Offline report for explicit model decisions, with a separate rule baseline."""
import html

def render_model_review(report, rows):
    esc=lambda x:html.escape(str(x),quote=True)
    model=report['model'];d=report['diagnostics'];events=report['events']
    end=max(report['duration_analyzed_s'],.01)
    points=lambda key:' '.join(f"{45+830*r['time_s']/end:.1f},{185-150*r[key]:.1f}" for r in rows)
    threshold_y=185-150*model['confidence_threshold']
    frames=''.join(f'''<figure><a href="{esc(f['file'])}"><img src="{esc(f['file'])}" alt="{f['time_s']:.2f}秒模型候选框" loading="lazy"></a><figcaption><b>{f['time_s']:.2f}s</b> · 模型最高置信度 {f.get('model_confidence',0):.1%}<small>规则边缘支持 {f['best_edge_ratio']:.1%} · {'模型候选' if f['candidate'] else '模型未触发'}</small></figcaption></figure>''' for f in report['review_frames'])
    event_rows=''.join(f"<tr><td>{i+1}</td><td>{e['start']:.2f}s</td><td>{e['confirmed_at']:.2f}s</td><td>{e['end']:.2f}s</td></tr>" for i,e in enumerate(events))
    event_table=f'<table><tr><th>候选</th><th>开始</th><th>确认</th><th>结束</th></tr>{event_rows}</table>' if events else '<p class="empty">未形成候选事件。请检查代表帧、模型类别及阈值；此结果不证明视频中没有火焰。</p>'
    return f'''<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>FireWatch · 模型视频报告</title><style>
*{{box-sizing:border-box}}body{{margin:0;background:#f4f6fa;color:#34445d;font:13px/1.8 -apple-system,BlinkMacSystemFont,sans-serif}}header{{padding:18px max(24px,calc((100vw - 1100px)/2));background:white;border-bottom:1px solid #e1e8f2;display:flex;justify-content:space-between}}a{{color:#5180b7;text-decoration:none}}main{{max-width:1100px;padding:28px 24px 45px;margin:auto}}h1{{font-size:28px;margin:0}}.muted,small{{color:#8b9bb0}}.top{{display:flex;justify-content:space-between;gap:20px}}.top nav{{display:flex;gap:16px;align-items:center;white-space:nowrap}}.insight{{padding:20px 23px;background:#eaf2fc;border-left:3px solid #6e9acc;margin:25px 0;border-radius:3px 10px 10px 3px}}.stats{{display:grid;grid-template-columns:repeat(4,1fr);gap:12px}}.stats>div,section{{border:1px solid #e1e8f1;background:white;border-radius:10px;padding:20px}}.stats b{{display:block;font-size:26px;font-weight:450}}section{{margin-top:20px}}h2{{font-size:16px;font-weight:500;margin:0 0 10px}}section p{{color:#7e92ac;font-size:12px}}svg{{display:block;width:100%;font-size:10px;fill:#92a2b8}}.legend{{font-size:10px;color:#7b8faa}}.frames{{display:grid;grid-template-columns:repeat(3,1fr);gap:14px}}figure{{border:1px solid #e2eaf4;border-radius:7px;overflow:hidden;margin:0}}img{{width:100%;aspect-ratio:16/9;object-fit:contain;background:#162333;display:block}}figcaption{{padding:10px;font-size:11px}}figcaption small{{display:block;font-size:10px}}table{{width:100%;border-collapse:collapse;text-align:left}}td,th{{border-bottom:1px solid #e8eef5;padding:10px;font-size:12px}}.fingerprint{{word-break:break-all;font:10px/1.9 ui-monospace,monospace;background:#f5f8fc;padding:12px;border-radius:6px}}footer{{color:#92a2b8;font-size:10px;margin-top:25px}}.filename{{overflow-wrap:anywhere}}@media(max-width:650px){{.top{{display:block}}.top nav{{margin-top:15px}}.stats{{grid-template-columns:1fr 1fr}}.frames{{grid-template-columns:1fr 1fr}}main{{padding:24px 15px}}section{{padding:16px}}h1{{font-size:23px}}}}
</style></head><body><header><b>▧ FireWatch · 模型视频分析</b><a href="/video">返回任务 →</a></header><main><div class="top"><div><h1>模型预测，与规则逐帧对照。</h1><div class="muted filename">{esc(report['source'])} · 已分析 {report['duration_analyzed_s']:.2f}s{' · 达到分析上限' if report['truncated'] else ''}</div></div><nav><a href="video-report.json">完整 JSON</a><a href="timeline.csv">逐帧 CSV</a></nav></div><div class="insight"><b>本次由 ONNX 模型形成候选事件，颜色与边缘规则仅作为独立基线。</b><div>模型最高置信度、规则边缘支持比例的定义不同，不能互相当作准确率。</div></div><div class="stats"><div>采样帧<b>{report['sampled_frames']}</b></div><div>模型候选帧<b>{d['candidate_frames']}</b></div><div>候选事件<b>{len(events)}</b></div><div>模型 / 规则分歧帧<b>{d['disagreement_frames']}</b></div></div><section><h2>模型得分与规则对照</h2><p>蓝线：保留下来的目标框最高模型置信度；绿线：规则边缘支持比例。无保留框时模型曲线记为 0；低于原分析阈值的框未保留。</p><div class="legend">蓝色 模型置信度 · 绿色 规则支持比例 · 虚线 模型阈值 {model['confidence_threshold']:.0%}</div><svg viewBox="0 0 920 215" role="img" aria-label="逐帧模型得分和规则边缘支持比例"><path d="M45 35H875 M45 110H875 M45 185H875" stroke="#e4ecf5" fill="none"/><path d="M45 {threshold_y:.1f}H875" stroke="#bb997e" stroke-dasharray="5 5"/><text x="0" y="39">100%</text><text x="10" y="190">0%</text><polyline points="{points('best_edge_ratio')}" stroke="#68a28c" stroke-width="2" fill="none"/><polyline points="{points('model_confidence')}" stroke="#648fc5" stroke-width="2.5" fill="none"/><text x="45" y="210">0s</text><text x="830" y="210">{end:.1f}s</text></svg></section><section><h2>候选事件</h2><p>连续 {report['on_frames']} 个模型阳性采样帧确认，连续 {report['off_frames']} 帧阴性后结束。未标注时不计算检测效果。</p>{event_table}</section><section><h2>代表帧与模型候选框</h2><div class="frames">{frames}</div></section><section><h2>模型来源与参数</h2><p>类别表：{esc(', '.join(model['class_names']))} · 目标类别索引：{esc(model['target_classes'])}<br>推理协议：{esc(model['output_layout'])} · 输入边长：{model['input_size']} · NMS IoU：{model['nms_iou']}</p><div class="fingerprint">MODEL SHA256: {esc(model['model_sha256'])}<br>ADAPTER SHA256: {esc(model['adapter_sha256'])}<br>VIDEO SHA256: {esc(report['source_sha256'])}</div></section><footer>本页证明分析流程及所用配置，不证明真实火焰识别准确率。请核对模型来源、类别与独立验证数据；恒定输出测试模型不可作为业务模型。</footer></main></body></html>'''
